import torch
import torch.nn as nn
from torch.utils.cpp_extension import load_inline

cuda_source = r"""
#include <torch/extension.h>
#include <cuda.h>
#include <cuda_runtime.h>

#define BLOCK_SIZE 512

__global__ void triplet_margin_loss_kernel(
    const float* __restrict__ anchor,
    const float* __restrict__ positive,
    const float* __restrict__ negative,
    float* __restrict__ result,
    int batch_size,
    int dim,
    float margin)
{
    __shared__ float shared_pos[BLOCK_SIZE / 32];
    __shared__ float shared_neg[BLOCK_SIZE / 32];
    float block_loss = 0.0f;
    for (int row = blockIdx.x; row < batch_size; row += gridDim.x) {
        const float* a = anchor + (size_t)row * dim;
        const float* p = positive + (size_t)row * dim;
        const float* n = negative + (size_t)row * dim;
        float sum_pos = 0.0f;
        float sum_neg = 0.0f;
        int dim4 = dim / 4;
        const float4* a4 = reinterpret_cast<const float4*>(a);
        const float4* p4 = reinterpret_cast<const float4*>(p);
        const float4* n4 = reinterpret_cast<const float4*>(n);
        #pragma unroll 4
        for (int i = threadIdx.x; i < dim4; i += blockDim.x) {
            float4 av4 = __ldg(&a4[i]);
            float4 pv4 = __ldg(&p4[i]);
            float4 nv4 = __ldg(&n4[i]);
            float da;
            da = av4.x - pv4.x; sum_pos += da * da;
            da = av4.y - pv4.y; sum_pos += da * da;
            da = av4.z - pv4.z; sum_pos += da * da;
            da = av4.w - pv4.w; sum_pos += da * da;
            float dn;
            dn = av4.x - nv4.x; sum_neg += dn * dn;
            dn = av4.y - nv4.y; sum_neg += dn * dn;
            dn = av4.z - nv4.z; sum_neg += dn * dn;
            dn = av4.w - nv4.w; sum_neg += dn * dn;
        }
        int tail_start = dim4 * 4;
        for (int i = tail_start + threadIdx.x; i < dim; i += blockDim.x) {
            float av = __ldg(&a[i]);
            float da = av - __ldg(&p[i]);
            float dn = av - __ldg(&n[i]);
            sum_pos += da * da;
            sum_neg += dn * dn;
        }
        // Warp-level reduction using shuffle instructions to minimize __syncthreads() overhead
        unsigned int mask = 0xffffffffu;
        #pragma unroll
        for (int offset = warpSize / 2; offset > 0; offset >>= 1) {
            sum_pos += __shfl_down_sync(mask, sum_pos, offset);
            sum_neg += __shfl_down_sync(mask, sum_neg, offset);
        }
        int lane = threadIdx.x % warpSize;
        int warp_id = threadIdx.x / warpSize;
        if (lane == 0) {
            shared_pos[warp_id] = sum_pos;
            shared_neg[warp_id] = sum_neg;
        }
        __syncthreads();
        if (warp_id == 0) {
            int num_warps = blockDim.x / warpSize;
            float final_pos = (lane < num_warps) ? shared_pos[lane] : 0.0f;
            float final_neg = (lane < num_warps) ? shared_neg[lane] : 0.0f;
            #pragma unroll
            for (int offset = warpSize / 2; offset > 0; offset >>= 1) {
                final_pos += __shfl_down_sync(mask, final_pos, offset);
                final_neg += __shfl_down_sync(mask, final_neg, offset);
            }
            if (lane == 0) {
                float dist_pos = sqrtf(final_pos);
                float dist_neg = sqrtf(final_neg);
                float loss = dist_pos - dist_neg + margin;
                loss = loss > 0.0f ? loss : 0.0f;
                block_loss += loss;
            }
        }
        __syncthreads();
    }
    if (threadIdx.x == 0) {
        atomicAdd(result, block_loss / static_cast<float>(batch_size));
    }
}
torch::Tensor triplet_margin_loss_cuda(
    torch::Tensor anchor,
    torch::Tensor positive,
    torch::Tensor negative,
    double margin)
{
    TORCH_CHECK(anchor.is_cuda(), "anchor must be a CUDA tensor");
    TORCH_CHECK(anchor.dim() == 2, "anchor must be 2D");
    auto anchor_c = anchor.contiguous();
    auto positive_c = positive.contiguous();
    auto negative_c = negative.contiguous();
    int batch_size = anchor_c.size(0);
    int dim = anchor_c.size(1);
    auto options = torch::TensorOptions().dtype(anchor_c.dtype()).device(anchor_c.device());
    auto result = torch::zeros({}, options);
    int device_id;
    cudaGetDevice(&device_id);
    cudaDeviceProp prop;
    cudaGetDeviceProperties(&prop, device_id);
    int max_blocks = prop.multiProcessorCount * 32;
    int grid_size = batch_size < max_blocks ? batch_size : max_blocks;
    if (grid_size < 1) grid_size = 1;
    dim3 grid(grid_size);
    dim3 block(BLOCK_SIZE);
    triplet_margin_loss_kernel<<<grid, block>>>(
        anchor_c.data_ptr<float>(),
        positive_c.data_ptr<float>(),
        negative_c.data_ptr<float>(),
        result.data_ptr<float>(),
        batch_size,
        dim,
        static_cast<float>(margin)
    );
    return result;
}
"""

cpp_source = r"""
torch::Tensor triplet_margin_loss_cuda(
    torch::Tensor anchor,
    torch::Tensor positive,
    torch::Tensor negative,
    double margin);
"""

triplet_loss_module = load_inline(
    name="triplet_loss_module",
    cpp_sources=cpp_source,
    cuda_sources=cuda_source,
    functions=["triplet_margin_loss_cuda"],
    verbose=False,
)


class ModelNew(nn.Module):
    """
    Optimized model that computes Triplet Margin Loss using a custom fused CUDA kernel.
    """
    def __init__(self, margin=1.0):
        super(ModelNew, self).__init__()
        self.margin = margin
        self.triplet_loss = triplet_loss_module

    def forward(self, anchor, positive, negative):
        return self.triplet_loss.triplet_margin_loss_cuda(
            anchor, positive, negative, self.margin
        )


batch_size = 32768
input_shape = (8192,)
dim = 1


def get_inputs():
    scale = torch.rand(())
    return [
        torch.rand(batch_size, *input_shape).cuda() * scale,
        torch.rand(batch_size, *input_shape).cuda(),
        torch.rand(batch_size, *input_shape).cuda(),
    ]


def get_init_inputs():
    return [1.0]  # Default margin

